	10280500: {
		names: [{ nominative: "Όσιος Αθανάσιος Α' Πατριάρχης Κωνσταντινούπολης", short: "Όσιος Αθανάσιος" }],
		biographies: [
			{
				id: "saintgr",
				copyright: "saint.gr",
				text: "Ο Όσιος Αθανάσιος γεννήθηκε στην Αδριανούπολη της Θράκης, από τους ευσεβείς γονείς Γεώργιο και Ευφροσύνη. Το πρώτο του όνομα ήταν Αλέξιος και ήταν άνθρωπος μεγάλης εγκράτειας και σωφροσύνης. Ασκήτευσε στο Άγιο Όρος και στο μοναστήρι του Γάνου.<br/><br/>Πατριάρχευσε δύο φορές. Την πρώτη φορά διαδέχτηκε τον Γρηγόριο, τον Κύπριο (1289 - 1293 μ.Χ.) και τη δεύτερη φορά (1304 - 1311 μ.Χ.) τον Ιωάννη IB'. Κατόπιν αποσύρθηκε του θρόνου και μόνασε σε κάποια Μονή, όπου απεβίωσε ειρηνικά σε ηλικία 100 χρονών.<br/><br/>Τη βιογραφία του συνέγραψε ο Ιωάννης Καλόθετος, σύγχρονος του Γρηγορίου Παλαμά και η μετάφραση αυτής έγινε από τον Αγάπιο Λάνδο στον \"Νέο Παράδεισο\".",
			},
		],
		info: [],
		refs: [],
		services: [],
		hymns: [],
	},
